std::thread_local!{static MD_RECONSTRUCT_ACTIVE:std::cell::Cell<bool>=const{std::cell::Cell::new(false)};}
pub(super) struct MdReconstructTestScope(bool);
impl MdReconstructTestScope{pub(super) fn enter()->Self{Self(MD_RECONSTRUCT_ACTIVE.with(|active|active.replace(true)))}}
impl Drop for MdReconstructTestScope{fn drop(&mut self){MD_RECONSTRUCT_ACTIVE.with(|active|active.set(self.0));}}

fn fixture()->MdSnapshot{semio_framework_pack_json::from_json_str(include_str!("../🧫️fixtures/🔣️.json"), semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn roundtrip(snapshot:&MdSnapshot)->MdSnapshot{let limits=SqliteDatabaseLimits::default();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let bytes=export_sqlite_database(&database,limits,&mut |_|true).unwrap();let database=import_sqlite_database(&bytes,limits,&mut |_|true).unwrap();MdSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap()}

#[test]
fn sqlite_snapshot_md_independent_consistent_surrogate_renumbering_retains_literal_tree(){
 use std::{io::Write,process::{Command,Stdio}};let limits=SqliteDatabaseLimits::default();let snapshot=fixture();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let bytes=export_sqlite_database(&database,limits,&mut |_|true).unwrap();let offset=cohort()["renumberOffset"].as_i64().unwrap();
 let script=format!("import {{Database}} from 'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));db.exec('PRAGMA foreign_keys=OFF');for(const{{name}}of db.query(\"SELECT name FROM sqlite_schema WHERE type='table'\").all()){{const key=db.query('PRAGMA table_info('+name+')').all().find(column=>column.pk===1).name;const links=db.query('PRAGMA foreign_key_list('+name+')').all();db.exec('UPDATE '+name+' SET '+[key+'='+key+'+{offset}',...links.filter(link=>link.from!==key).map(link=>link.from+'='+link.from+'+{offset}')].join(','));}}if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');await Bun.write(Bun.stdout,db.serialize());db.close();");
 let mut child=Command::new("bun").args(["-e",&script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let result=child.wait_with_output().unwrap();assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stderr));let database=import_sqlite_database(&result.stdout,limits,&mut |_|true).unwrap();let restored=MdSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored,snapshot);let dialect=store::io_schema::ArtifactDialect{artifact_kind:"s.stdio.md".into(),standard:"commonmark".into(),subset:"*".into()};snapshot.validate_sqlite_snapshot_subset(&dialect,&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();restored.retire_sqlite_snapshot();snapshot.retire_sqlite_snapshot();
}

