#[test]
fn sqlite_snapshot_md_independent_sqlite_queries_and_edits_tree_entities(){
 use std::{io::Write,process::{Command,Stdio}};let limits=SqliteDatabaseLimits::default();let mut expected=fixture();let database=expected.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let bytes=export_sqlite_database(&database,limits,&mut |_|true).unwrap();
 let script="import {Database} from 'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const head=db.query('SELECT h.level,t.text FROM md_document_block b JOIN md_heading h ON h.id=b.block_id JOIN md_block_inline i ON i.block_id=h.id JOIN md_text t ON t.id=i.inline_id WHERE b.ordinal=0 AND i.ordinal=0').get();if(head.level!==255||head.text!=='Alpha 世界\\0')throw Error('semantic heading');if(db.query('SELECT start FROM md_list WHERE start IS NOT NULL').get().start!==4294967295)throw Error('u32');db.query('UPDATE md_text SET text=? WHERE id=(SELECT inline_id FROM md_block_inline WHERE block_id=(SELECT block_id FROM md_document_block WHERE ordinal=0) AND ordinal=0)').run('edited 世界');db.query('UPDATE md_heading SET level=0').run();await Bun.write(Bun.stdout,db.serialize());db.close();";
 let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let result=child.wait_with_output().unwrap();assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stderr));let database=import_sqlite_database(&result.stdout,limits,&mut |_|true).unwrap();let MdBlock::Heading{level,inlines}=&mut expected.blocks[0]else{panic!()};*level=0;let MdInline::Text{text}=&mut inlines[0]else{panic!()};*text="edited 世界".into();assert_eq!(MdSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),expected);
}

#[test]
fn sqlite_snapshot_md_rejects_invalid_ownership_ordinals_tags_and_bounds(){let snapshot=fixture();let limits=SqliteDatabaseLimits::default();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();for(table,column,value)in [("md_heading",1,SqliteValue::Integer(256)),("md_block",1,SqliteValue::Text("paragraph".into())),("md_document_block",2,SqliteValue::Integer(99)),("md_block_inline",1,SqliteValue::Integer(999))]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows[0].values[column]=value;assert!(MdSnapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err(),"{table}");}assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,limits)).is_err());assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:1,..limits})).is_err());assert!(MdSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:16,..limits})).is_err());}

