#[test]
fn sqlite_snapshot_md_whole_native_control_keeps_deep_fields_and_interior_cancellation(){
 use store::sqlite_snapshot::SqliteSnapshotPhase;
 let cases:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🛬️controlled.json")).unwrap();let depth=cases["depth"].as_u64().unwrap()as usize;let mut inline=MdInline::Text{text:"exact literal 世界".into()};for _ in 0..depth{inline=MdInline::Emphasis{inlines:vec![inline]};}let mut block=MdBlock::List{ordered:false,start:Some(cases["orderedStart"].as_u64().unwrap()as u32),tight:false,items:vec![vec![],vec![MdBlock::Paragraph{inlines:vec![inline]}]]};for _ in 0..depth{block=MdBlock::BlockQuote{blocks:vec![block]};}
 let snapshot=MdSnapshot{schema:"owned logical schema 世界".repeat(cases["schemaRepeat"].as_u64().unwrap()as usize),blocks:vec![block]};let limits=SqliteDatabaseLimits::default();
 for payload in[store::io_schema::IoPayload::Binary(store::ArtifactPack::encode_pack(&snapshot)),store::io_schema::IoPayload::Text(store::ArtifactDsl::print_dsl(&snapshot))]{
  let restored=MdSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored.schema,snapshot.schema);let mut block=&restored.blocks[0];let mut count=0;while let MdBlock::BlockQuote{blocks}=block{count+=1;block=&blocks[0];}assert_eq!(count,depth);let MdBlock::List{ordered,start,tight,items}=block else{panic!()};assert!(!ordered&&!tight);assert_eq!(*start,Some(u32::MAX));assert!(items[0].is_empty());restored.retire_sqlite_snapshot();
  for limits in[SqliteDatabaseLimits{max_rows:cases["maxRows"].as_u64().unwrap()as usize,..limits},SqliteDatabaseLimits{max_allocation_bytes:cases["maxAllocationBytes"].as_u64().unwrap()as usize,..limits}]{assert!(MdSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());}
  let mut interior=false;assert!(MdSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |event|{if event.phase==SqliteSnapshotPhase::DecodeNative&&event.completed>=cases["cancelAfter"].as_u64().unwrap()as usize&&event.completed<event.total{interior=true;false}else{true}},limits)).is_err());assert!(interior);
 }
 snapshot.retire_sqlite_snapshot();
}

#[test]
fn sqlite_snapshot_md_final_sql_checkpoint_cancellation_retires_complete_deep_tree(){
 const CHILD:&str="SEMIO_MD_FINAL_SQL_CANCEL_CHILD";
 if std::env::var_os(CHILD).is_none(){
  let qualified=concat!(module_path!(),"::sqlite_snapshot_md_final_sql_checkpoint_cancellation_retires_complete_deep_tree");let selector=qualified.split_once("::").expect("actual crate/module boundary").1;
  let output=std::process::Command::new(std::env::current_exe().unwrap()).args([selector,"--exact","--test-threads=1"]).env(CHILD,"1").output().unwrap();let stdout=String::from_utf8_lossy(&output.stdout);let stderr=String::from_utf8_lossy(&output.stderr);
  assert!(output.status.success()&&stdout.contains("test result: ok. 1 passed"),"isolated final SQL cancellation law must really execute and pass: {stdout}{stderr}");return;
 }
 std::thread::Builder::new().stack_size(64*1024).spawn(||{
  use store::sqlite_snapshot::SqliteSnapshotPhase;let depth=cohort()["lateSqlCancellationDepth"].as_u64().unwrap()as usize;let mut block=MdBlock::HtmlBlock{raw:"retained final SQL literal 世界\0".into()};for _ in 0..depth{block=MdBlock::BlockQuote{blocks:vec![block]};}let snapshot=MdSnapshot{schema:"literal final SQL checkpoint schema".into(),blocks:vec![block]};let limits=SqliteDatabaseLimits::default();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();
  crate::standards::v_commonmark::subsets::any::io::sqlite::snapshot::owned_pack::reset_retirement_visits_for_test();let mut reached=false;let result=MdSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |event|{if event.phase==SqliteSnapshotPhase::ReconstructSnapshot&&event.completed==1&&event.total==1{assert!(!reached,"actual final checkpoint runs once");reached=true;false}else{true}},limits));
  let visits=crate::standards::v_commonmark::subsets::any::io::sqlite::snapshot::owned_pack::retirement_visits_for_test();snapshot.retire_sqlite_snapshot();assert!(reached,"refusal must occur at the actual final reconstructed SQL snapshot checkpoint");assert!(result.is_err(),"late cancellation cannot publish the completed snapshot");assert!(visits>=depth+1,"all completed owned nodes must use cold retirement at the final refusal; observed {visits}, expected at least {}",depth+1);
 }).unwrap().join().unwrap();
}

#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_md_public_allocation_budget_is_independent_of_semantic_values() {
    use semio_framework_os_kernel::io::{ArtifactDialect, io_mechanism::{io_export_sqlite_snapshot, io_import_sqlite_snapshot, io_route, io_run_with_snapshot_control}};
    use semio_framework_os_kernel::io_schema::{IoPayload, SQLITE_SNAPSHOT};
    use semio_framework_os_kernel::sqlite_snapshot::{SnapshotEncoding, SqliteSnapshotPhase};
    semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("md allocation declaration").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();
    let dialect: ArtifactDialect = crate::MD_DIALECT.into();
    let snapshot = fixture(); let limits = SqliteDatabaseLimits::default();
    let route = io_route(&ArtifactDialect::from(SQLITE_SNAPSHOT), &dialect, 1).await.unwrap().value;
    for encoding in [SnapshotEncoding::Binary, SnapshotEncoding::Text] {
        let mut native_phase = false;
        let bytes = io_export_sqlite_snapshot(&dialect, &snapshot, encoding, limits, &mut |event| { native_phase |= matches!(event.phase, SqliteSnapshotPhase::DecodeNative | SqliteSnapshotPhase::EncodeNative); true }).await.unwrap().value;
        assert!(!native_phase, "typed full-file export must bypass native carrier production");
        let database = import_sqlite_database(&bytes, limits, &mut |_| true).unwrap();
        let semantic: usize = database.tables.iter().flat_map(|table| &table.rows).flat_map(|row| &row.values).map(|value| match value { SqliteValue::Null => 0, SqliteValue::Integer(_) | SqliteValue::Real(_) => 8, SqliteValue::Text(text) => text.len(), SqliteValue::Blob(bytes) => bytes.len() }).sum();
        use std::{io::Write, process::{Command, Stdio}};
        let script = "import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');let count=0;for(const{name}of db.query(\"SELECT name FROM sqlite_schema WHERE type='table'\").all())for(const row of db.query('SELECT * FROM \"'+name.replaceAll('\"','\"\"')+'\"').all())for(const value of Object.values(row))count+=value===null?0:typeof value==='number'||typeof value==='bigint'?8:typeof value==='string'?new TextEncoder().encode(value).length:value.byteLength;await Bun.write(Bun.stdout,String(count));db.close();";
        let mut child = Command::new("bun").args(["-e", script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap(); child.stdin.take().unwrap().write_all(&bytes).unwrap(); let oracle = child.wait_with_output().unwrap(); assert!(oracle.status.success(), "{}", String::from_utf8_lossy(&oracle.stderr)); assert_eq!(String::from_utf8(oracle.stdout).unwrap().parse::<usize>().unwrap(), semantic);
        let exact = SqliteDatabaseLimits { max_value_bytes: semantic, ..limits };
        let restored = io_import_sqlite_snapshot::<MdSnapshot>(&dialect, &bytes, exact, &mut |event| { native_phase |= matches!(event.phase, SqliteSnapshotPhase::DecodeNative | SqliteSnapshotPhase::EncodeNative); true }).await.unwrap().value;
        assert_eq!(restored, snapshot); assert!(!native_phase); restored.retire_sqlite_snapshot();
        let output = io_run_with_snapshot_control(&route, IoPayload::Binary(bytes.clone()), exact, &mut |_| true).await.expect("semantic SQL bytes must not become the native backing ceiling").value;
        assert_eq!(matches!(output, IoPayload::Text(_)), encoding == SnapshotEncoding::Text);
        let refused = io_run_with_snapshot_control(&route, IoPayload::Binary(bytes), SqliteDatabaseLimits { max_allocation_bytes: 1, ..exact }, &mut |_| true).await;
        assert!(refused.is_err(), "actual public native output must enforce independent backing admission");
    }
    snapshot.retire_sqlite_snapshot();
}

